// trainer.cpp — macOS (Apple Silicon / Intel), C++17, Mach VM API
// Value-scan trainer for single-player games / your own processes.
//
// Build: clang++ -std=c++17 -O2 trainer.cpp -o trainer
// Run:   sudo ./trainer <pid>        (find pid with: pgrep -l <name>)
//
// Notes: task_for_pid needs root, and the target must not be built with the
// hardened runtime (or must carry the get-task-allow entitlement). Apple's own
// signed apps are off-limits under SIP. Windows titles under CrossOver/Whisky
// run inside a wine process; attach to that pid.
//
// Commands:
//   scan <int>     first scan: every 4-byte-aligned int32 equal to <int>
//   next <int>     keep only matches whose current value equals <int>
//   changed        keep matches whose value changed since last scan
//   same           keep matches whose value did not change
//   list           show up to 20 matches with live values
//   set <int>      write <int> to all matches
//   freeze <int>   keep writing <int> to all matches every 50 ms
//   unfreeze       stop freezing
//   reset          clear matches
//   quit

#include <mach/mach.h>
#include <mach/mach_vm.h>

#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

struct Region {
    mach_vm_address_t addr;
    mach_vm_size_t size;
};

struct Match {
    mach_vm_address_t addr;
    int32_t last;
};

static mach_port_t g_task = MACH_PORT_NULL;
static std::atomic<bool> g_freezing{false};
static std::thread g_freezeThread;

static bool readMem(mach_vm_address_t addr, void* buf, mach_vm_size_t size) {
    mach_vm_size_t got = 0;
    kern_return_t kr = mach_vm_read_overwrite(g_task, addr, size,
                                              reinterpret_cast<mach_vm_address_t>(buf), &got);
    return kr == KERN_SUCCESS && got == size;
}

static bool writeInt(mach_vm_address_t addr, int32_t value) {
    kern_return_t kr = mach_vm_write(g_task, addr,
                                     reinterpret_cast<vm_offset_t>(&value),
                                     sizeof(value));
    return kr == KERN_SUCCESS;
}

static std::vector<Region> writableRegions() {
    std::vector<Region> out;
    mach_vm_address_t addr = 0;
    for (;;) {
        mach_vm_size_t size = 0;
        vm_region_basic_info_data_64_t info;
        mach_msg_type_number_t count = VM_REGION_BASIC_INFO_COUNT_64;
        mach_port_t objName = MACH_PORT_NULL;
        kern_return_t kr = mach_vm_region(g_task, &addr, &size, VM_REGION_BASIC_INFO_64,
                                          reinterpret_cast<vm_region_info_t>(&info),
                                          &count, &objName);
        if (kr != KERN_SUCCESS) break;
        const vm_prot_t rw = VM_PROT_READ | VM_PROT_WRITE;
        if ((info.protection & rw) == rw) out.push_back({addr, size});
        addr += size;
    }
    return out;
}

static std::vector<Match> firstScan(int32_t target) {
    std::vector<Match> matches;
    const mach_vm_size_t chunk = 1 << 20;
    std::vector<uint8_t> buf(chunk);

    for (const Region& r : writableRegions()) {
        for (mach_vm_size_t off = 0; off < r.size; off += chunk) {
            mach_vm_size_t len = std::min(chunk, r.size - off);
            if (!readMem(r.addr + off, buf.data(), len)) continue;
            for (mach_vm_size_t i = 0; i + sizeof(int32_t) <= len; i += sizeof(int32_t)) {
                int32_t v;
                std::memcpy(&v, buf.data() + i, sizeof(v));
                if (v == target) matches.push_back({r.addr + off + i, v});
            }
        }
    }
    return matches;
}

enum class Filter { Equal, Changed, Same };

static void refine(std::vector<Match>& matches, Filter f, int32_t target = 0) {
    std::vector<Match> kept;
    kept.reserve(matches.size());
    for (const Match& m : matches) {
        int32_t v;
        if (!readMem(m.addr, &v, sizeof(v))) continue;
        bool keep = (f == Filter::Equal && v == target) ||
                    (f == Filter::Changed && v != m.last) ||
                    (f == Filter::Same && v == m.last);
        if (keep) kept.push_back({m.addr, v});
    }
    matches.swap(kept);
}

static void stopFreeze() {
    if (g_freezing.exchange(false) && g_freezeThread.joinable()) g_freezeThread.join();
}

static void startFreeze(std::vector<mach_vm_address_t> addrs, int32_t value) {
    stopFreeze();
    g_freezing = true;
    g_freezeThread = std::thread([addrs = std::move(addrs), value] {
        while (g_freezing) {
            for (mach_vm_address_t a : addrs) writeInt(a, value);
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: sudo %s <pid>\n", argv[0]);
        return 1;
    }
    pid_t pid = static_cast<pid_t>(std::atoi(argv[1]));
    kern_return_t kr = task_for_pid(mach_task_self(), pid, &g_task);
    if (kr != KERN_SUCCESS) {
        std::fprintf(stderr,
                     "task_for_pid(%d) failed: %s\n"
                     "run with sudo; target must not use the hardened runtime.\n",
                     pid, mach_error_string(kr));
        return 1;
    }
    std::printf("attached to pid %d\n", pid);

    std::vector<Match> matches;
    std::string line;
    while (std::printf("> "), std::fflush(stdout), std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string cmd;
        in >> cmd;
        long long arg = 0;
        bool hasArg = static_cast<bool>(in >> arg);
        int32_t v = static_cast<int32_t>(arg);

        if (cmd == "scan" && hasArg) {
            matches = firstScan(v);
            std::printf("%zu matches\n", matches.size());
        } else if (cmd == "next" && hasArg) {
            refine(matches, Filter::Equal, v);
            std::printf("%zu matches\n", matches.size());
        } else if (cmd == "changed") {
            refine(matches, Filter::Changed);
            std::printf("%zu matches\n", matches.size());
        } else if (cmd == "same") {
            refine(matches, Filter::Same);
            std::printf("%zu matches\n", matches.size());
        } else if (cmd == "list") {
            for (size_t i = 0; i < matches.size() && i < 20; ++i) {
                int32_t cur = 0;
                bool ok = readMem(matches[i].addr, &cur, sizeof(cur));
                std::printf("  0x%016llx  %s%d\n",
                            static_cast<unsigned long long>(matches[i].addr),
                            ok ? "" : "(unreadable) ", cur);
            }
            if (matches.size() > 20) std::printf("  ... %zu more\n", matches.size() - 20);
        } else if (cmd == "set" && hasArg) {
            size_t ok = 0;
            for (const Match& m : matches) ok += writeInt(m.addr, v);
            std::printf("wrote %d to %zu/%zu addresses\n", v, ok, matches.size());
        } else if (cmd == "freeze" && hasArg) {
            std::vector<mach_vm_address_t> addrs;
            for (const Match& m : matches) addrs.push_back(m.addr);
            startFreeze(std::move(addrs), v);
            std::printf("freezing %zu addresses at %d\n", matches.size(), v);
        } else if (cmd == "unfreeze") {
            stopFreeze();
            std::printf("unfrozen\n");
        } else if (cmd == "reset") {
            matches.clear();
            std::printf("cleared\n");
        } else if (cmd == "quit" || cmd == "exit") {
            break;
        } else if (!cmd.empty()) {
            std::printf("commands: scan N | next N | changed | same | list | set N | "
                        "freeze N | unfreeze | reset | quit\n");
        }
    }

